_GENERATED_RE = re.compile(r"# AUTOGENERATED! DO NOT EDIT! File to edit: (.+)")

# %% ../nbs/11_agent_workbench.ipynb #08f2048f
def _run_git(root, *args):
    proc = subprocess.run(["git", "-C", str(root), *args], text=True, capture_output=True)
    return proc.stdout if proc.returncode == 0 else ""

# %% ../nbs/11_agent_workbench.ipynb #68a43b61
def _git_root(path="."):
    path = Path(path).expanduser()
    base = path.parent if path.suffix else path
    out = _run_git(base, "rev-parse", "--show-toplevel").strip()
    return Path(out) if out else None

# %% ../nbs/11_agent_workbench.ipynb #9f69b97a
def _git_status_paths(root):
    paths = set()
    for line in _run_git(root, "status", "--porcelain").splitlines():
        raw = line[3:].strip()
        if " -> " in raw: raw = raw.split(" -> ", 1)[1]
        if raw: paths.add(raw)
    return paths

# %% ../nbs/11_agent_workbench.ipynb #34d44fa9
def _git_tracked_paths(root):
    return set(_run_git(root, "ls-files").splitlines())

# %% ../nbs/11_agent_workbench.ipynb #5d123864
def _git_diff_stats(root):
    stats = {}
    for line in _run_git(root, "diff", "--numstat", "HEAD", "--").splitlines():
        added, deleted, path = line.split("\t", 2)
        stats[path] = {
            "added": int(added) if added.isdigit() else 0,
            "deleted": int(deleted) if deleted.isdigit() else 0,
        }
    return stats

# %% ../nbs/11_agent_workbench.ipynb #8f5275e0
def _file_hash(path):
    path = Path(path)
    if not path.exists() or not path.is_file(): return None
    return hashlib.sha256(path.read_bytes()).hexdigest()

# %% ../nbs/11_agent_workbench.ipynb #8bba4674
def _line_count(path):
    try: return len(Path(path).read_text(encoding="utf-8", errors="ignore").splitlines())
    except OSError: return 0

# %% ../nbs/11_agent_workbench.ipynb #ff632798
def _notebook_paths(path):
    path = Path(path).expanduser()
    if path.is_file() and path.suffix == ".ipynb": return [path]
    if path.is_dir():
        return sorted(p for p in path.rglob("*.ipynb") if ".ipynb_checkpoints" not in p.parts)
    return []

# %% ../nbs/11_agent_workbench.ipynb #429f878b
def _source_without_directives(source):
    return "\n".join(line for line in source.splitlines() if not line.lstrip().startswith("#|"))

# %% ../nbs/11_agent_workbench.ipynb #62cb8654
def _public_symbols_in_cell(cell):
    if "exported_code" not in cell_class_names(cell): return []
    try: tree = ast.parse(_source_without_directives(cell_source(cell)))
    except SyntaxError: return []
    return [
        node.name for node in tree.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)) and not node.name.startswith("_")
    ]

# %% ../nbs/11_agent_workbench.ipynb #449cea07
def _notebook_cell_hashes(path):
    try: nb = _read_nb(path)
    except FileNotFoundError: return {}
    return {getattr(cell, "id", f"idx-{idx}"): cell_hash(cell, n=None) for idx, cell in enumerate(nb.cells)}

# %% ../nbs/11_agent_workbench.ipynb #d2503c21
def _notebook_public_symbols(path):
    try: nb = _read_nb(path)
    except FileNotFoundError: return []
    symbols = []
    for cell in nb.cells:
        symbols.extend(_public_symbols_in_cell(cell))
    return sorted(set(symbols))

# %% ../nbs/11_agent_workbench.ipynb #cb6b7e24
def _generated_owner(path):
    path = Path(path)
    if path.suffix != ".py" or not path.exists(): return None
    try:
        for line in path.read_text(encoding="utf-8", errors="ignore").splitlines()[:3]:
            match = _GENERATED_RE.match(line.strip())
            if match: return (path.parent / match.group(1).rstrip(".")).resolve()
    except OSError:
        return None
    return None

# %% ../nbs/11_agent_workbench.ipynb #84c23b83
def _generated_pairs(root):
    pairs = []
    for path in Path(root).rglob("*.py"):
        if any(part in {".git", ".venv", "__pycache__"} for part in path.parts): continue
        owner = _generated_owner(path)
        if owner is not None: pairs.append((path, owner))
    return pairs

